export const code = async (inputs) => {
  return {
    to: inputs.webhook_body.to,
    subject: inputs.webhook_body.subject,
    body: inputs.webhook_body.body,
    lead_id: inputs.webhook_body.lead_id,
    step_id: inputs.webhook_body.step_id
  };
};

export const code = async (inputs) => {
  let htmlBody = inputs.body.replace(/\n/g, '<br>');

  // Append unsubscribe link
  const unsubscribeLink = `${inputs.base_url}/opt-out?lead=${inputs.lead_id}`;

  htmlBody += `
  <hr style="margin-top: 30px; border: none; border-top: 1px solid #eee;">
  <p style="font-size: 12px; color: #999; text-align: center;">
    You are receiving this email because you requested a mortgage quote from Nyra.<br>
    <a href="${unsubscribeLink}" style="color: #666;">Unsubscribe</a> | 
    <a href="${inputs.base_url}/privacy" style="color: #666;">Privacy Policy</a>
  </p>`;

  return { 
    html_body: htmlBody,
    text_body: inputs.body + `\n\nTo unsubscribe, visit: ${unsubscribeLink}`
  };
};

export const code = async (inputs) => {
  const metric = {
    job: 'campaign_engine',
    instance: 'activepieces',
    labels: {
      channel: 'email',
      step_id: inputs.step_id,
      lead_id: inputs.lead_id,
      status: inputs.success ? 'sent' : 'failed'
    },
    value: 1,
    timestamp: Date.now()
  };

  console.log('Email Metric:', metric);

  return metric;
};

